import sys
from collections import Counter

def find_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def check_divisors(x, y, divisors):
    return Counter(find_divisors(x)) + Counter(find_divisors(y)) == divisors

def restore_numbers(n, divisors):
    divisors = Counter(divisors)
    for x in range(1, divisors[1] + 1):
        if divisors[x] == 2:
            remaining_divisors = divisors - Counter(find_divisors(x))
            for y in range(1, remaining_divisors[1] + 1):
                if remaining_divisors[y] == 2 and check_divisors(x, y, divisors):
                    return x, y
    return None

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    divisors = list(map(int, data[1:]))
    x, y = restore_numbers(n, divisors)
    print(x, y)

if __name__ == "__main__":
    main()

