import sys
from itertools import combinations

def read_input():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    k = int(data[2])
    matrix = []
    index = 3
    for i in range(n):
        row = list(map(int, data[index:index + m]))
        matrix.append(row)
        index += m
    return n, m, k, matrix

def max_sum_divisible_by_k(n, m, k, matrix):
    max_sum = 0
    for row in matrix:
        row_sum = sum(row)
        if row_sum % k == 0:
            max_sum = max(max_sum, row_sum)
        else:
            for r in range(1, (m // 2) + 1):
                for combo in combinations(row, r):
                    combo_sum = sum(combo)
                    if combo_sum % k == 0:
                        max_sum = max(max_sum, combo_sum)
    return max_sum

def main():
    n, m, k, matrix = read_input()
    result = max_sum_divisible_by_k(n, m, k, matrix)
    print(result)

