def find_longest_increasing_subsequence(n, a):
    from collections import deque
    left, right = deque(), deque()
    left.append(a[0])
    right.append(a[-1])

    for i in range(1, n):
        if a[i] > left[-1]:
            left.append(a[i])
        else:
            left.appendleft(a[i])

    for i in range(n-2, -1, -1):
        if a[i] > right[-1]:
            right.append(a[i])
        else:
            right.appendleft(a[i])

    i, j = 0, n-1
    result = []
    while i < len(left) and j >= 0:
        if left[i] < right[j]:
            result.append('L')
            i += 1
        else:
            result.append('R')
            j -= 1

    return len(result), ''.join(result)

