    n = int(data[0])
    a = list(map(int, data[1:]))
    return n, a

def can_take_left(i, j, a):
    return a[i] < a[j]

def can_take_right(i, j, a):
    return a[i] < a[j]

def solve(n, a):
    left = [0] * n
    right = [0] * n
    left[0] = 1
    right[n-1] = 1

    for i in range(1, n):
        if can_take_left(i-1, i, a):
            left[i] = left[i-1] + 1
        else:
            left[i] = 1

    for i in range(n-2, -1, -1):
        if can_take_right(i, i+1, a):
            right[i] = right[i+1] + 1
        else:
            right[i] = 1

    max_length = 0
    moves = []
    i, j = 0, n-1

    while i <= j:
        if left[i] >= right[j]:
            moves.append('L')
            i += 1
        else:
            moves.append('R')
            j -= 1
        max_length += 1

    return max_length, ''.join(moves)

def main():
    n, a = read_input()
    max_length, moves = solve(n, a)
    print(max_length)
    print(moves)

