def find_longest_increasing_subsequence(n, a):
    from collections import deque
    left = deque()
    right = deque()
    left.append(a[0])
    right.append(a[-1])

    for i in range(1, n):
        if a[i] > left[-1]:
            left.append(a[i])
        else:
            left.appendleft(a[i])

    for i in range(n-2, -1, -1):
        if a[i] > right[-1]:
            right.append(a[i])
        else:
            right.appendleft(a[i])

    max_length = 0
    moves = []

    while left and right:
        if left[0] < right[0]:
            moves.append('L')
            max_length += 1
            left.popleft()
        else:
            moves.append('R')
            max_length += 1
            right.popleft()

