def can_append(left, right, stack):
    if not stack:
        return True
    if left > stack[-1] and right > stack[-1]:
        return left > right
    if left > stack[-1]:
        return True
    if right > stack[-1]:
        return True
    return False

def longest_increasing_sequence(n, a):
    left, right = 0, n - 1
    stack = []
    moves = []

    while left <= right:
        if can_append(a[left], a[right], stack):
            if a[left] < a[right]:
                stack.append(a[left])
                moves.append('L')
                left += 1
            else:
                stack.append(a[right])
                moves.append('R')
                right -= 1
        elif a[left] < a[right]:
            stack.append(a[left])
            moves.append('L')
            left += 1
        else:
            stack.append(a[right])
            moves.append('R')
            right -= 1

    return len(stack), ''.join(moves)

