import sys

def find_cycle(graph, start):
    visited = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        stack.extend(graph[node])
    return visited

def find_disjoint_sets(graph, n):
    sets = []
    for i in range(1, n + 1):
        if i not in [node for s in sets for node in s]:
            sets.append(find_cycle(graph, i))
    return sets

def assign_gifts(graph, n):
    assigned = [0] * (n + 1)
    for s in find_disjoint_sets(graph, n):
        if len(s) == 1:
            assigned[s[0]] = s[0]
        else:
            for i in range(len(s)):
                assigned[s[i]] = s[(i + 1) % len(s)]
    return assigned

