def count_operations(n, x, y, number):
    target_remainder = 10 ** y
    current_remainder = int(number[-x:]) % target_remainder
    operations = 0

    for i in range(n - 1, -1, -1):
        if i < x:
            if current_remainder % 10 != 0:
                operations += 1
                current_remainder -= 1
        else:
            if number[i] == '1':
                operations += 1
                current_remainder -= 10 ** (i - x)
                current_remainder %= target_remainder

    return operations

