import sys
from collections import defaultdict

def can_schedule(n, m, exams):
    # Initialize the schedule with zeros
    schedule = [0] * n

    # Dictionary to store the preparation days for each exam
    prep_days = defaultdict(list)

    # Check if it's possible to schedule the exams
    for s, d, c in exams:
        if d - s < c:
            return -1
        prep_days[s].append((d, c))

    # Sort preparation days by start day
    for s in prep_days:
        prep_days[s].sort(key=lambda x: x[0])

    # Try to schedule exams
    for s in range(1, n + 1):
        if schedule[s - 1] != 0:
            continue
        for d, c in prep_days[s]:
            if d - s >= c:
                schedule[s - 1] = d
                c -= 1
                if c == 0:
                    prep_days[s].remove((d, c))
                break

    # Check if all exams are scheduled
    for s, d, c in exams:
        if schedule[s - 1] == 0:
            return -1

    return schedule

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    exams = []

