        s = int(data[index])
        d = int(data[index + 1])
        c = int(data[index + 2])
        exams.append((s, d, c))
        index += 3

    result = can_schedule(n, m, exams)

    if result == -1:
        print(result)
    else:
        print(' '.join(map(str, result)))

