def is_valid_schedule(schedule: List[int], exams: List[List[int]]) -> bool:
    n = len(schedule)
    m = len(exams)
    preparation = [0] * (m + 1)

    for i in range(1, n):
        if schedule[i] == 0:
            continue
        if schedule[i] == (m + 1):
            if schedule[i-1] != (m + 1):
                return False
        else:
            exam = schedule[i]
            if preparation[exam] >= exams[exam-1][2]:
                return False
            preparation[exam] += 1

    for i in range(1, m + 1):
        if preparation[i] != exams[i-1][2]:
            return False

    return True

def find_schedule(n: int, m: int, exams: List[List[int]]) -> List[int]:
    schedule = [0] * n
    for i in range(m):
        exam = exams[i]
        start, end, prepare = exam[0], exam[1], exam[2]
        for j in range(start, end):
            if schedule[j] == 0:
                schedule[j] = i + 1
                prepare -= 1
                if prepare == 0:
                    break
        if prepare != 0:
            return [-1]
    return schedule

