def find_schedule(n, m, exams):
    days = [0] * n
    exam_queue = deque(sorted(exams, key=lambda x: x[1]))
    prepare_days = defaultdict(int)

    for day in range(n):
        if exam_queue and exam_queue[0][1] == day + 1:
            exam = exam_queue.popleft()
            days[day] = exam[0]
            prepare_days[exam[0]] += 1
        elif prepare_days:
            exam = min(prepare_days, key=prepare_days.get)
            days[day] = exam
            prepare_days[exam] -= 1
        else:
            days[day] = 0

    if is_valid_schedule(days, exams):
        return days
    else:
        return None

