def calculate_time_to_repair(k, t):
    return t

def calculate_time_to_drive(k, a):
    return k * a

def calculate_time_to_walk(k, b):
    return k * b

def calculate_minimal_time(d, k, a, b, t):
    if d <= k:
        return d * a

    car_drives = d // k
    remaining_distance = d % k

    if remaining_distance > 0:
        car_drives += 1

    repair_time = (car_drives - 1) * calculate_time_to_repair(k, t)
    drive_time = car_drives * calculate_time_to_drive(k, a)
    walk_time = remaining_distance * b

    return repair_time + drive_time + walk_time

