def calculate_driving_time(distance, speed):
    return distance * speed

def calculate_repair_time(repair_interval, repair_time):
    return repair_interval + repair_time

def optimal_driving_strategy(d, k, a, b, t):
    if d <= k:
        return calculate_driving_time(d, a)

    full_drives = d // k
    remaining_distance = d % k

    driving_time = full_drives * calculate_driving_time(k, a)
    repair_time = full_drives * calculate_repair_time(k, t)

    if remaining_distance > 0:
        driving_time += calculate_driving_time(remaining_distance, a)
        if remaining_distance >= k:
            repair_time += calculate_repair_time(k, t)

    walking_time = calculate_driving_time(remaining_distance, b) if remaining_distance > 0 else 0

    return driving_time + repair_time + walking_time

def main():
