def count_pairs(n, m):
    # Count the number of integers in each column that have a remainder of 0, 1, 2, 3, or 4 when divided by 5
    remainder_counts = [0] * 5
    for i in range(1, n + 1):
        remainder_counts[i % 5] += 1
    for i in range(1, m + 1):
        remainder_counts[i % 5] += 1

    # Calculate the number of valid pairs
    count = 0
    for x in range(5):
        for y in range(5):
            if (x + y) % 5 == 0:
                count += remainder_counts[x] * remainder_counts[y]

    # Since each pair (x, y) is counted twice (once as (x, y) and once as (y, x)), divide by 2
    return count // 2

