def digit_count(n):
    """Calculate the total number of digits contributed by numbers up to n."""
    if n < 10:
        return n
    elif n < 100:
        return 90 + (n - 9)
    elif n < 1000:
        return 900 + 90 * (n - 99)
    elif n < 10000:
        return 9000 + 900 * (n - 999)
    elif n < 100000:
        return 90000 + 9000 * (n - 9999)
    elif n < 1000000:
        return 900000 + 90000 * (n - 99999)
    elif n < 10000000:
        return 9000000 + 900000 * (n - 999999)
    elif n < 100000000:
        return 90000000 + 9000000 * (n - 9999999)
    elif n < 1000000000:
        return 900000000 + 90000000 * (n - 99999999)
    elif n < 10000000000:
        return 9000000000 + 900000000 * (n - 999999999)
    else:
        return 90000000000 + 9000000000 * (n - 9999999999)

def find_number_at_position(k):
    """Find the number that contains the k-th digit."""
    n = 1
    while digit_count(n) < k:
        n *= 10
    k -= digit_count(n - 1)
    return int(str(n) + str(k - 1))

def get_digit_at_position(k):
    """Get the k-th digit from the infinite sequence."""
    number = find_number_at_position(k)
    position_within_number = (k - 1) % len(str(number))
    return int(str(number)[position_within_number])

