def max_bourles(n, m, r, s, b):
    s.sort()
    b.sort(reverse=True)
    i, j = 0, 0
    shares = 0
    while i < n and j < m:
        if s[i] <= b[j]:
            shares += r // s[i]
            r = r % s[i]
            i += 1
        else:
            if shares > 0:
                money = shares * b[j]
                if money > r:
                    shares = r // b[j]
                    r = r % b[j]
                else:
                    shares = 0
                    r = 0
                j += 1
            else:
                break
    while i < n:
        shares += r // s[i]
        r = r % s[i]
        i += 1
    while j < m:
        if shares > 0:
            money = shares * b[j]
            if money > r:
                shares = r // b[j]
                r = r % b[j]
            else:
                shares = 0
                r = 0
            j += 1
        else:
            break
    return r + shares * b[j-1] if j > 0 else r

